<?php

declare(strict_types=1);

namespace Database\Seeders;

use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\DB;
use Illuminate\Support\Facades\Schema;

/**
 * Bootstrap snapshot of the site builder: pages, page components (classic and
 * golden themes) and their repeated content rows, exactly as `DB/digikash.sql`
 * ships them.
 *
 * An installation that never imported the dump came up with all three tables
 * empty — no landing page sections, no component library to open, no
 * privacy/terms pages. This seeder restores that baseline.
 *
 * `pages.component_ids` references components by numeric id, and a bare
 * `migrate` already backfills a couple of components with ids of its own, so
 * the dump's ids cannot be assumed. Components are therefore matched by
 * (component_key, theme) — existing rows are kept, missing ones inserted —
 * and every dump id is remapped through the resulting table before pages
 * store their component lists. Pages themselves only seed into an empty
 * `pages` table: a site where an administrator has already built pages is
 * never touched. Additive throughout, so it is safe in
 * `installer.reconcile_seeders`.
 *
 * GoldenThemeComponentSeeder remains the per-component upgrade path for
 * existing installations; running it after this one is a no-op.
 */
class SiteBuilderSeeder extends Seeder
{
    public function run(): void
    {
        foreach (['pages', 'page_components', 'page_component_repeated_contents'] as $table) {
            if (! Schema::hasTable($table)) {
                return;
            }
        }

        DB::transaction(function (): void {
            $idMap   = [];
            $created = [];

            foreach ($this->components() as $component) {
                $dumpId = $component['id'];
                unset($component['id']);

                $existing = DB::table('page_components')
                    ->where('component_key', $component['component_key'])
                    ->where('theme', $component['theme'])
                    ->value('id');

                if ($existing !== null) {
                    $idMap[$dumpId] = (int) $existing;

                    continue;
                }

                $component['page_id'] = null;

                $idMap[$dumpId]   = (int) DB::table('page_components')->insertGetId($this->stamp($component));
                $created[$dumpId] = true;
            }

            foreach ($this->repeatedContents() as $row) {
                if (! isset($created[$row['component_id']])) {
                    continue;
                }

                DB::table('page_component_repeated_contents')->insert($this->stamp([
                    'component_id' => $idMap[$row['component_id']],
                    'content_data' => $row['content_data'],
                ]));
            }

            if (DB::table('pages')->exists()) {
                return;
            }

            foreach ($this->pages() as $page) {
                $componentIds = array_values(array_filter(array_map(
                    fn ($dumpId): ?int => $idMap[(int) $dumpId] ?? null,
                    json_decode((string) $page['component_ids'], true) ?: [],
                )));

                $page['component_ids'] = json_encode(array_map('strval', $componentIds));

                DB::table('pages')->insert($this->stamp($page));
            }

            $this->relinkComponentPages($idMap, $created);
        });
    }

    /**
     * A handful of components point back at the page that owns them
     * (`blog_standard` → the Blog page). They are inserted detached, because
     * the dump's page ids only mean anything once the pages above actually
     * seeded — into an empty table, keeping their dump ids. Only components
     * this run created are relinked; anything that predates this seeder keeps
     * whatever an administrator wired up.
     *
     * @param array<int, int>  $idMap
     * @param array<int, bool> $created
     */
    private function relinkComponentPages(array $idMap, array $created): void
    {
        foreach ($this->components() as $component) {
            if ($component['page_id'] === null || ! isset($created[$component['id']])) {
                continue;
            }

            DB::table('page_components')
                ->where('id', $idMap[$component['id']])
                ->update(['page_id' => $component['page_id']]);
        }
    }

    /**
     * @param  array<string, mixed> $row
     * @return array<string, mixed>
     */
    private function stamp(array $row): array
    {
        $now = now();

        return $row + ['created_at' => $now, 'updated_at' => $now];
    }

